import Foundation

/// Self-contained, generated from the same localized descriptions as the app.
/// No remote resources, credentials, filesystem paths or executable scripts.
enum CommanderHandbook {
    struct Chapter { let id: String; let title: String; let text: String }
    static func escape(_ text: String) -> String {
        text.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;").replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#39;")
    }
    static let anchors = ["anfang", "oberflaeche", "navigation", "dateien", "uebertragungen", "wiederherstellen", "orte", "cloud", "teilen", "server", "laufwerke", "medien", "archive", "werkzeuge", "einstellungen", "tastatur", "probleme", "wissen"]
    /// Match the Linux handbook's eighteen topics, with native Mac controls and
    /// explicit implementation limits rather than Linux-only installation steps.
    static func complete(_ base: [Chapter], german: Bool) -> [Chapter] {
        func chapter(_ id: String, _ de: String, _ en: String, _ deText: String, _ enText: String) -> Chapter {
            Chapter(id: id, title: german ? de : en, text: german ? deText : enText)
        }
        let additional = [
            chapter("oberflaeche", "Die Oberfläche verstehen", "Understand the interface",
                "Zwei Dateibereiche navigieren unabhängig. Klicke zuerst in die Seite, deren Auswahl du bearbeiten möchtest. Die farbige Linie und Spaltenüberschriften unterscheiden die Seiten. Jeder Bereich enthält Pfad, Ordnerbaum, Namensfilter und Dateiliste.\n\nOben stehen Dateiaktionen, Suchen, Werkzeuge, Hilfe, Einstellungen und Verbindungen. Die Orte-Leiste enthält Ziele, keine Verwaltungsbefehle. Historie und Übertragungen lassen sich getrennt öffnen. Hilfe und Einstellungen bleiben neben der Dateiarbeit geöffnet.",
                "Two file panes navigate independently. Click the pane whose selection you want to use first. The colored line and headings distinguish the panes. Each pane contains a path, folder tree, name filter and file list.\n\nThe top toolbar contains file actions, Search, Tools, Help, Settings and Connections. The Locations bar contains destinations, not management commands. History and Transfers open separately. Help and Settings can stay open alongside file work."),
            chapter("navigation", "Ordner öffnen und Dateien auswählen", "Navigate and select files",
                "Doppelklick oder Return öffnet einen Ordner. Ein einfacher Klick markiert einen Eintrag; ein weiterer Klick nimmt ihn aus der Auswahl. Command+A markiert die angezeigten Dateien. Sortiere über Name, Größe, Typ oder Datum.\n\nLokal kannst du einen vollständigen Pfad in die Pfadzeile eingeben. Online öffnest du Ordner in derselben Dateiliste oder im Ordnerbaum. Zurück, Vorwärts und der Aufwärtspfeil navigieren im jeweiligen Bereich. Die Trennlinie zwischen Baum und Liste lässt sich ziehen.\n\nDer Namensfilter gilt nur für die aktuelle Liste. Eine leere Trefferliste ist nicht zwangsläufig ein leerer Ordner. Filter löschen oder Escape im Filterfeld zeigt die geladenen Einträge wieder. Die Suche durchsucht dagegen auch Unterordner.",
                "Double-click or Return opens a folder. One click selects an entry; another removes it from the selection. Command+A selects the displayed files. Sort using Name, Size, Type or Date.\n\nLocally, enter an absolute path in the path field. Online, open folders in the same file list or folder tree. Back, Forward and the Up arrow navigate the corresponding pane. Drag the divider to resize the tree.\n\nThe name filter applies only to the current list. No matches does not necessarily mean an empty folder. Clear filter or Escape in the filter field restores the loaded entries. Search also examines subfolders."),
            chapter("dateien", "Kopieren, verschieben und verwalten", "Copy, move and manage files",
                "Öffne Quelle und Ziel in den beiden Bereichen. F5 kopiert die aktive Auswahl in die andere Seite, F6 verschiebt sie. Command+C kopiert, Command+X merkt zum Verschieben vor und Command+V fügt am Ziel ein. Ausschneiden allein entfernt keine Datei.\n\nDrag-and-Drop kann auf die andere Liste oder einen Zielordner erfolgen. Prüfe vorher den Modus Kopieren/Verschieben. Bei vorhandenen Namen beantwortest du den Konfliktdialog; Abbrechen startet diesen Auftrag nicht. Ein eingestellter Online- oder Server-Ort bleibt im normalen Bereich.\n\nErst Abgeschlossen bestätigt den Erfolg. Fehler sind kein Abschlussnachweis. Bei Online-Übertragungen können Inhaltsprüfungen länger dauern als der sichtbare Datentransfer. Verändere Quelle und Ziel nicht gleichzeitig in anderen Programmen.",
                "Open the source and destination in the two panes. F5 copies the active selection to the other pane; F6 moves it. Command+C copies, Command+X marks a move and Command+V pastes at the destination. Cutting alone removes nothing.\n\nDrag and drop onto the other list or a destination folder. Check the Copy/Move mode first. Answer the conflict dialog for existing names; Cancel does not start that job. Online and server locations stay in the regular pane.\n\nOnly Completed confirms success. An error is not a completion result. Online content verification can take longer than the visible transfer. Do not simultaneously modify the source or destination in another program."),
            chapter("wiederherstellen", "Historie und Rückgängig", "History and Undo",
                "Die Historie zeigt Dateiaktionen mit Uhrzeit und Rücknahmeoption. Rückgängig prüft zuerst, ob die betroffenen Inhalte noch unverändert sind. Ein belegter ursprünglicher Name, geänderte Daten oder ein fehlendes Laufwerk können die Rücknahme verhindern.\n\nKopien werden nicht blind gelöscht und ersetzte Originale bleiben für die Rücknahme gesichert. Lokale Verschiebeaufträge können eine versteckte Wiederherstellungskopie der Quelle behalten. Entferne diese Daten nicht, solange du sie noch für Rückgängig benötigst.\n\nBeim Ersetzen durch Kopieren in synchronisierten Cloud-Ordnern wird die alte Version zusätzlich außerhalb der Synchronisierung unter Application Support/OpenCommander/CloudRecovery gesichert. Diese geprüften Sicherungen benötigen lokalen Speicher und werden nicht automatisch gelöscht. Der genaue Sicherungspfad steht in den Historie-Details.\n\nOnline-Ersetzen bewahrt die Vorgängerversion im Anbieterordner. Unterstützte Online-Aktionen speichern geprüfte Rücknahmeverweise dauerhaft. Rückgängig in der Werkzeugleiste verwendet die neueste rücknehmbare Aktion der gemeinsamen Historie, unabhängig vom aktiven Bereich. Nach einem Neustart werden Konto, Wiederherstellungsverweise und Inhalte erneut geprüft; eine fehlende Verbindung oder veränderte Datei stoppt die Rücknahme. Ersetzte Ordner werden vollständig ersetzt, nicht zusammengeführt.\n\nBei OneDrive kann ein Löschen in den Anbieter-Papierkorb erfolgen. Direkte rclone-Cloudverbindungen behalten stattdessen einen gekennzeichneten Wiederherstellungsort; das ist nicht der Anbieter-Papierkorb. Historie ist kein unabhängiges Backup. Das Entfernen einer fertigen Transferkarte entfernt nur die Karte.",
                "History shows file actions with timestamps and Undo controls. Undo first verifies that the affected content is unchanged. An occupied original name, changed content or a disconnected drive can prevent recovery.\n\nCopies are not blindly deleted and replaced originals are retained for Undo. Local move jobs can retain a hidden source recovery copy. Keep those files while you still need Undo.\n\nCopy replacement in synchronized cloud folders additionally saves the previous version outside synchronization in Application Support/OpenCommander/CloudRecovery. These verified backups use local disk space and are not automatically deleted. History Details show the exact recovery path.\n\nOnline replacement retains the previous version in the provider folder. Supported online operations persist verified Undo references. Toolbar Undo uses the latest recoverable action in the shared chronological History, regardless of the active pane. After restart, accounts, recovery references and content are checked again; a missing connection or changed file stops recovery. Replaced folders are replaced completely, not merged.\n\nOneDrive deletion can use the provider recycle bin. Direct rclone cloud connections instead retain a named recovery location; this is not the provider recycle bin. History is not an independent backup. Removing a completed transfer card removes only the card."),
            chapter("orte", "Orte und Dienstsymbole", "Locations and provider icons",
                "Einstellungen / Orte enthält Namen, Sichtbarkeit und Reihenfolge. Mit den Schaltern blendest du Orte ein oder aus; mit dem Sortiergriff ordnest du sie an. Ein Anzeigename benennt die Verknüpfung um, nicht den echten Ordner. Ort hinzufügen öffnet die Auswahl für lokale und konfigurierte Online-Ziele.\n\nAktive Cloud-Ordner tragen Dienstsymbole. Deaktivierte File-Provider-Orte und aufbewahrte lokale Cloud-Archive sind als solche bezeichnet. Ein nicht angeschlossenes Laufwerk ist kein leerer Ordner. OneDrive online ist von einem lokalen OneDrive-Synchronisierungsordner getrennt.",
                "Settings / Locations contains names, visibility and ordering. Use switches to show or hide places and reorder handles to arrange them. A display name renames the shortcut, not the actual folder. Add location offers local and configured online destinations.\n\nActive cloud folders have provider icons. Disabled file-provider locations and retained local cloud archives are identified accordingly. A disconnected drive is not an empty directory. OneDrive Online is separate from a local OneDrive synchronization folder."),
            chapter("teilen", "Cloud-Dateien bewusst teilen", "Share cloud files deliberately",
                "Direkte OneDrive-, Google-Drive- und Dropbox-Verbindungen können im Dateimenü einen öffentlichen Freigabelink erstellen oder abrufen. Bestätige die Warnung erst, wenn die ausgewählte Datei oder der ausgewählte Ordner für Personen mit dem Link zugänglich sein soll, möglicherweise ohne Anmeldung und dauerhaft. Prüfe bestehende Anbieterrechte. Abbrechen vor Erstellen ändert nichts; Abbrechen nach der Erstellung widerruft die Freigabe nicht. Entferne sie bei Bedarf auf der Anbieter-Webseite.\n\nFirmenrichtlinien können öffentliche Links verhindern. Für nicht unterstützte Anbieter verwende deren Webseite. Links werden weder automatisch kopiert noch geöffnet. Kopieren und Verschieben sind keine Freigabeaktionen und dürfen die Kontorechte nicht stillschweigend erweitern.",
                "Direct OneDrive, Google Drive and Dropbox connections can create or retrieve a public sharing link from the file menu. Confirm the warning only if the selected file or folder should be accessible to people with the link, potentially without sign-in and indefinitely. Check existing provider permissions. Cancel before Create changes nothing; cancelling after creation does not revoke sharing. Revoke it on the provider website when needed.\n\nCompany policies can prohibit public links. Use the website for unsupported providers. Links are not copied or opened automatically. Copying and moving are not sharing actions and must not silently expand account permissions."),
            chapter("server", "SFTP, FTP und FTPS verbinden", "Connect SFTP, FTP and FTPS",
                "Verbindungen verwaltet eigene Serverprofile mit Namen, Adresse, Port, Benutzer und Startordner. Online-Server öffnen im selben Dateibereich und unterstützen Ordnernavigation sowie Dateiaktionen. Ein SFTP-Zugang verwendet SSH; FTP überträgt ohne Verschlüsselung und sollte nicht für vertrauliche Daten über fremde Netze verwendet werden. Nutze dort SFTP oder FTPS.\n\nPrüfe bei SSH den Fingerabdruck des Servers unabhängig, bevor du einem neuen Host vertraust. Bestätige Zertifikats- oder Sicherheitshinweise nicht blind. Passwörter gehören nicht in Orte-Namen, Fehlerberichte oder Screenshots. Eine fehlende Anmeldung oder Schreibberechtigung kann die App nicht selbst ersetzen.",
                "Connections manages server profiles with a name, address, port, user and starting folder. Servers open in the same file pane with folder navigation and file actions. SFTP uses SSH; FTP is unencrypted and should not carry confidential data across untrusted networks. Use SFTP or FTPS there.\n\nVerify an SSH server fingerprint independently before trusting a new host. Do not blindly accept certificate or security warnings. Passwords do not belong in location names, bug reports or screenshots. The app cannot replace missing login or write permissions."),
            chapter("laufwerke", "USB, NAS, Netzlaufwerke und NTFS", "USB, NAS, network drives and NTFS",
                "Angeschlossene und eingebundene Laufwerke erscheinen als Orte. Der Mac-Ort bildet das lokale Wurzelsystem ab. Apple-Systembereiche können trotz Festplattenvollzugriff schreibgeschützt bleiben. Netzwerkfreigaben müssen erreichbar und angemeldet sein. Eine NAS-Freigabe kann andere Rechte haben als ein lokaler Ordner.\n\nNTFS-Schreiben benötigt die passende OpenCommander-FSKit-Erweiterung, ihre manuelle Freigabe und einen schreibfähigen Mount. Festplattenvollzugriff ersetzt die Erweiterungsfreigabe nicht. Ein nur lesbar eingebundenes NTFS-Laufwerk bleibt nur lesbar. Formatiere keine vorhandene Festplatte, um eine Fehlermeldung zu umgehen.\n\nPausiere und warte auf den gespeicherten Status, bevor du ein Laufwerk auswirfst. Verbinde zum Fortsetzen dasselbe Laufwerk. Unbekannte Laufwerksidentitäten oder veränderte Teildaten werden nicht blind übernommen.",
                "Attached and mounted drives appear as locations. The Mac location represents the local filesystem root. Apple system areas can remain read-only even with Full Disk Access. Network shares must be reachable and authenticated; a NAS share can have different permissions from a local folder.\n\nNTFS writing requires the matching OpenCommander FSKit extension, manual approval and a writable mount. Full Disk Access does not replace extension approval. A read-only NTFS mount remains read-only. Do not format an existing drive to bypass an error.\n\nPause and wait for the saved status before ejecting a drive. Reconnect the same drive to resume. Unknown drive identities or changed partial data are not blindly adopted."),
            chapter("medien", "Bilder, Videos und Vorschau", "Images, video and preview",
                "Vorschau oder Leertaste öffnet die aktive Auswahl. Unterstützte Bilder und Medien können intern angezeigt werden; Öffnen verwendet die Standardanwendung des Mac. Bei nicht unterstützten Formaten wähle Öffnen mit.\n\nOnline-Vorschauen benötigen zuerst einen Download und freien lokalen Speicher. Sie sind keine vollständige Offline-Kopie des Kontos. Ein Ladefehler darf nicht als leere Datei interpretiert werden. Vorschau und temporäres Öffnen sind nicht automatisch ein Zurückspeichern nach OneDrive oder zu einem Server.\n\nDer Papierkorb in der Medienvorschau fragt vor dem Entfernen nach. Bei Online-Dateien betrifft er das Original beim Anbieter, nicht nur die heruntergeladene Vorschau. Erst eine erfolgreiche Entfernung wechselt zum nächsten Medium. Rückgängig und die jeweilige Wiederherstellung bleiben über die Historie zugänglich; Archivmitglieder lassen sich hier nicht löschen.\n\nUnterstützte native Google-Dokumente werden in ein geeignetes Dateiformat exportiert. Das Ergebnis ist eine eigenständige Kopie, kein bearbeitbares Original und kein automatisches Zurückspeichern. Exportgrößen können zunächst unbekannt sein; Anbieterlimits und Sicherheitsprüfungen gelten weiterhin.",
                "Preview or Space opens the active selection. Supported images and media can be shown internally; Open uses the Mac's default application. Choose Open With for unsupported formats.\n\nOnline previews first need a download and free local storage. They are not a complete offline copy of the account. A loading error must not be interpreted as an empty file. Preview and temporary external opening do not automatically save edits back to OneDrive or a server.\n\nThe media preview trash button asks before removal. For online files it affects the provider original, not just the downloaded preview. Only successful removal advances to the next item. Undo and applicable recovery remain accessible through History; archive members cannot be deleted here.\n\nSupported native Google documents are exported to an appropriate file format. The result is an independent copy, not an editable original or automatic writeback. Export sizes can initially be unknown; provider limits and safety checks still apply."),
            chapter("archive", "Archive öffnen und entpacken", "Open and extract archives",
                "ZIP sowie unterstützte TAR-, TGZ-, BZ2-, XZ-, 7z- und RAR-Dateien lassen sich wie Ordner durchsuchen. Wähle einzelne Einträge oder Unterordner und Entpacken, um sie in den anderen Bereich zu übernehmen. ZIP erstellt ein neues Archiv aus der aktiven Auswahl.\n\nNicht jeder Decoder oder verschlüsselte Archivtyp wird unterstützt. Unsichere Pfade, symbolische Links, besondere Dateitypen und mehrdeutige Namenskonflikte werden beim Entpacken abgewiesen. Für die native Entpackfunktion gelten Grenzen von 100.000 Einträgen und 4 GiB entpackten Daten; die Archivvorschau ist auf 128 MiB begrenzt.\n\nEin Archiv ist kein normaler schreibbarer Ordner. Dateien werden erst nach erfolgreichem Entpacken als reguläre Dateien verwendet. Ein Fehler bedeutet nicht, dass das ganze Archiv erfolgreich übernommen wurde.",
                "ZIP and supported TAR, TGZ, BZ2, XZ, 7z and RAR files can be browsed like folders. Select entries or subfolders and Extract to place them in the other pane. ZIP creates a new archive from the active selection.\n\nNot every decoder or encrypted archive is supported. Unsafe paths, symbolic links, special file types and ambiguous name conflicts are rejected during extraction. Native extraction is limited to 100,000 entries and 4 GiB unpacked data; archive previews are limited to 128 MiB.\n\nAn archive is not an ordinary writable directory. Entries become regular files only after extraction succeeds. An error does not mean the whole archive was successfully transferred."),
            chapter("werkzeuge", "Suchen, vergleichen und mehrfach umbenennen", "Search, compare and batch rename",
                "Suchen öffnet einen Dialog mit dem Pfad des aktiven Bereichs. Du kannst den Startpfad ändern. Groß-/Kleinschreibung beachten ist standardmäßig ausgeschaltet. Suchresultate zeigen den Pfad, damit gleichnamige Treffer unterscheidbar bleiben. Die Suche ist von dem Filter der aktuellen Dateiliste getrennt.\n\nWerkzeuge enthält Vergleichen und Mehrfach umbenennen. Prüfe Quelle und Ziel sowie die Vorschau vor einer Änderung. Namenskonflikte, ungültige Namen und veränderte Online-Einträge werden nicht einfach ignoriert. Ein Vergleich zeigt Unterschiede; er ersetzt kein Backup.\n\nGroße oder entfernte Ordner benötigen Zeit zum Laden und Prüfen. Nutze die Fortschrittsanzeige und breche bei Bedarf ab. Online-Ergebnisse sind der geladene Stand und können danach durch andere Programme geändert werden.",
                "Search opens a dialog starting at the active pane's path. You can change the starting path. Case sensitivity is off by default. Results show their paths so identically named entries remain distinguishable. Search is separate from the current file-list filter.\n\nTools contains Compare and Batch Rename. Check the source, destination and preview before applying changes. Name conflicts, invalid names and changed online entries are not silently ignored. A comparison identifies differences; it does not replace a backup.\n\nLarge or remote folders take time to load and verify. Watch progress and cancel when needed. Online results describe the loaded state and can subsequently change through other programs."),
            chapter("einstellungen", "Einstellungen und Eigenschaften", "Settings and properties",
                "Sprache wird über das Dropdown in Einstellungen / Orte gewählt. Dunkel schaltet die Darstellung um. Einstellungen können während der Dateiarbeit geöffnet bleiben; nötige Änderungen an der Hauptansicht werden sicher nach Abschluss der laufenden Aktion oder nach Schließen des Panels angewendet.\n\nNamen, Sichtbarkeit und Reihenfolge der Orte werden gespeichert. Entfernen einer Verknüpfung entfernt nicht ihre Dateien und widerruft keine Cloud-Anmeldung. Festplattenvollzugriff und FSKit-Freigaben bestätigst du in den macOS-Einstellungen selbst.\n\nCommand+I zeigt Informationen zur aktiven Datei. Nicht jede Eigentümer-, Zeit- oder Dateisystem-Eigenschaft lässt sich auf jedem Anbieter ändern. Verlasse dich bei einem experimentellen NTFS-Laufwerk nicht darauf, dass alle Mac-Metadaten übernommen werden.",
                "Choose Language from the Settings / Locations dropdown. Dark changes appearance. Settings can stay open during file work; necessary main-window rebuilds apply safely after the current action or after the panel closes.\n\nLocation names, visibility and order are saved. Removing a shortcut does not remove its files or revoke a cloud login. You confirm Full Disk Access and FSKit approval yourself in macOS Settings.\n\nCommand+I shows information about the active file. Not every ownership, timestamp or filesystem attribute can be changed on every provider. Do not assume experimental NTFS drives preserve all Mac metadata."),
            chapter("wissen", "Begriffe und gespeicherte Daten", "Terms and stored data",
                "Aktiver Bereich: Die Seite, deren Auswahl für Kurzbefehle verwendet wird. Ort: Eine gespeicherte Verknüpfung zu einem Ziel. Mount: Ein vom Betriebssystem eingebundenes Laufwerk. Cache: Ein zeitweiliger Listen- oder Vorschauzwischenspeicher, kein Backup.\n\nEinstellungen, Historie und Auftragsindex gehören zum lokalen App-Profil. Versteckte Ordner wie .OpenCommanderJob-…, .OpenCommanderMoved-… und .OpenCommander-Recovery-… können Teildaten oder Wiederherstellungskopien enthalten. Verändere sie nicht während eines zugehörigen Auftrags.\n\nCloud-Zugangsdaten gehören nicht in die Historie oder Orte-Namen. Eine ausdrücklich gewählte private rclone-Konfiguration kann dem Helfer Kontozugriff geben. Wähle nur vertrauenswürdige Konfigurationen. Diagnose kopieren kopiert Daten lokal; prüfe persönliche Pfade vor dem Weitergeben. Dieses Handbuch lädt keine externen Inhalte. Seine eingebaute Suche verarbeitet Suchwörter nur als Text, nicht als auszuführenden Code.",
                "Active pane: the side whose selection keyboard actions use. Location: a saved shortcut to a destination. Mount: a drive attached by the operating system. Cache: a temporary listing or preview store, not a backup.\n\nPreferences, History and the job index belong to the local app profile. Hidden folders such as .OpenCommanderJob-…, .OpenCommanderMoved-… and .OpenCommander-Recovery-… can contain partial data or recovery copies. Do not modify them during their related jobs.\n\nCloud credentials do not belong in History or location names. An explicitly selected private rclone configuration can grant the helper account access; select only trusted configurations. Copy Diagnostics copies data locally; review personal paths before sharing it. This handbook loads no external content. Its built-in search treats queries as text, not executable code.")]
        var indexed: [String: Chapter] = [:]
        for chapter in base + additional where anchors.contains(chapter.id) && indexed[chapter.id] == nil { indexed[chapter.id] = chapter }
        if let keyboard = indexed["tastatur"] {
            let external = german
                ? "Beim Ziehen aus dem Finder: Option kopiert, Command verschiebt über die native macOS-Dateiannahme. Alternativ vor dem Ziehen den Schalter auf Verschieben stellen. Nur zugängliche Originaldateien können verschoben werden, keine temporären Exporte. Die Quelle wird erst nach erfolgreicher Übertragung aus ihrem ursprünglichen Ort entfernt; Rückgängig bleibt verfügbar. Innerhalb von OpenCommander gelten ebenfalls Option für Kopieren und Command für Verschieben. Command+Option-Verknüpfungen werden nicht unterstützt. Beim Herausziehen bestimmt das Zielprogramm die unterstützten Aktionen; Online- und ZIP-Exporte zum Finder sind Kopien."
                : "When dragging from Finder: Option copies; Command moves through the native macOS file receiver. Alternatively select Move before dragging. Only accessible original files can be moved, not temporary exports. The source leaves its original location only after a successful transfer; Undo remains available. Within OpenCommander, Option also copies and Command moves. Command-Option links are not supported. Other destination apps determine their supported actions; online and ZIP exports to Finder are copies."
            let pathShortcut = german ? "Command+L oder Command+Umschalt+G öffnet den Pfaddialog des aktiven Bereichs." : "Command+L or Command+Shift+G opens the active pane's folder dialog."
            indexed["tastatur"] = Chapter(id: keyboard.id, title: keyboard.title, text: keyboard.text + "\n\n" + external + "\n\n" + pathShortcut)
        }
        if let properties = indexed["einstellungen"] {
            let scan = german ? "Die Ordnergröße wird erst mit Ordnergröße berechnen ermittelt. Symbolischen Links wird nicht gefolgt. Bei Lesefehlern oder Zeit-/Eintragsgrenzen erscheint die bekannte Größe ausdrücklich als Teilresultat mit Fehlerzahl und Grund. Wiederherstellungsordner von OpenCommander werden dabei ausgelassen." : "Folder size is scanned only after Calculate folder size. Symbolic links are not followed. Read errors or time/entry limits show the known size explicitly as a partial result with error count and reason. OpenCommander's private recovery directories are excluded."
            indexed["einstellungen"] = Chapter(id: properties.id, title: properties.title, text: properties.text + "\n\n" + scan)
        }
        if let cloud = indexed["cloud"] {
            let extra = german ? "Eigene Desktop-App-Registrierung ist optional im neuen Cloud-Assistenten. Leer lassen verwendet eine mitgelieferte Herausgeber-Registrierung oder den Backend-Standard. OneDrive und Dropbox verwenden mit einer eigenen Registrierung die sichere Browser-Anmeldung mit PKCE, ohne Client-Secret. Die Registrierung muss die Desktop-Umleitung http://localhost:53682/ erlauben. Google benötigt eine Installed-Desktop-ID und deren Desktop-Secret, keine Server-Zugangsdaten. Benutzer müssen kein Azure- oder Entwicklerkonto anlegen, wenn der Herausgeber eine freigegebene Registrierung mitliefert. Die Anbieterfreigabe und tatsächliche Kontoanmeldung bleiben erforderlich. Bestehende Konten werden nicht auf eine andere Registrierung umgestellt." : "A custom desktop app registration is optional in the new cloud assistant. Leave empty to use a publisher-provided registration or the backend default. Custom OneDrive and Dropbox registrations use secure browser PKCE without a client secret. The registration must permit the desktop redirect http://localhost:53682/. Google requires an installed-desktop ID and its desktop secret, not server credentials. Users do not need an Azure or developer account when the publisher supplies an approved registration. Provider approval and actual user sign-in are still required. Existing accounts are not migrated to another registration."
            indexed["cloud"] = Chapter(id: cloud.id, title: cloud.title, text: cloud.text + "\n\n" + extra)
        }
        return anchors.compactMap { indexed[$0] }
    }
    /// Trusted host-side search only. Query is a callAsyncJavaScript argument;
    /// no user text is interpreted as markup, code or an unescaped expression.
    static let searchScript = #"""
    let state = window.__commanderHandbookSearch;
    if (!state || state.needle !== needle) {
      for (const mark of document.querySelectorAll('mark[data-commander-hit]')) {
        const parent = mark.parentNode;
        mark.replaceWith(document.createTextNode(mark.textContent));
        parent.normalize();
      }
      state = {needle, hits: [], index: 0};
      window.__commanderHandbookSearch = state;
      if (needle && needle.length <= 200) {
        const expression = new RegExp(needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'giu');
        const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        const nodes = [];
        while (walker.nextNode()) {
          const node = walker.currentNode;
          if (!node.parentElement.closest('script,style')) nodes.push(node);
        }
        for (const node of nodes) {
          const matches = [...node.textContent.matchAll(expression)];
          if (!matches.length) continue;
          const fragment = document.createDocumentFragment(); let offset = 0;
          for (const match of matches) {
            fragment.append(document.createTextNode(node.textContent.slice(offset, match.index)));
            const mark = document.createElement('mark'); mark.dataset.commanderHit = 'true';
            mark.textContent = match[0]; fragment.append(mark); state.hits.push(mark);
            offset = match.index + match[0].length;
          }
          fragment.append(document.createTextNode(node.textContent.slice(offset)));
          node.replaceWith(fragment);
        }
      }
    } else if (advance && state.hits.length) {
      state.index = (state.index + (backwards ? -1 : 1) + state.hits.length) % state.hits.length;
    }
    for (const hit of state.hits) hit.classList.remove('commander-current-hit');
    const current = state.hits[state.index];
    if (current) {
      current.classList.add('commander-current-hit');
      current.scrollIntoView({block: 'center', inline: 'nearest', behavior: 'instant'});
    }
    return {count: state.hits.length, index: state.index};
    """#

    static func html(_ chapters: [Chapter], german: Bool) -> String {
        let contents = chapters.filter { anchors.contains($0.id) }.map {
            "<section id=\"\($0.id)\"><h2>\(escape($0.title))</h2><p>\(escape($0.text).replacingOccurrences(of: "\n", with: "<br>"))</p><a href=\"#anfang\">↑ \(german ? "Zum Anfang" : "Back to top")</a></section>"
        }.joined()
        let navigation = chapters.filter { anchors.contains($0.id) }.map { "<a href=\"#\($0.id)\">\(escape($0.title))</a>" }.joined()
        let left = german ? "Quelle / aktiver Bereich" : "Source / active pane"
        let right = german ? "Ziel / anderer Bereich" : "Destination / other pane"
        return """
        <!doctype html><html lang="\(german ? "de" : "en")"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
        <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:">
        <title>OpenCommander · \(german ? "Handbuch" : "Handbook")</title>
        <style>mark[data-commander-hit]{background:#ffe680;color:#111}mark.commander-current-hit{background:#ffad33;outline:2px solid #7f4b00}@media print{mark[data-commander-hit]{background:transparent;color:inherit;outline:none}}</style>
        <style>:root{color-scheme:light dark}body{font:16px -apple-system,system-ui;line-height:1.6;margin:24px;color:CanvasText;background:Canvas}h1{font-size:28px}h2{font-size:21px}nav{display:flex;flex-wrap:wrap;gap:12px}a{color:LinkText}section{margin-top:32px;border-top:1px solid GrayText;padding-top:12px}svg{width:100%;height:auto}rect{fill:Canvas;stroke:GrayText}text{fill:CanvasText;font:16px -apple-system,system-ui}.notice{background:color-mix(in srgb,CanvasText 7%,Canvas);padding:12px;border-radius:8px}p{overflow-wrap:anywhere}@media print{:root{color-scheme:light}body{font-size:11pt;color:#111;background:white}h1,h2{break-after:avoid}p{orphans:3;widows:3}section>a{display:none}nav{font-size:9pt}svg{break-inside:avoid}}</style></head><body>
        <h1>OpenCommander · macOS</h1><p class="notice">\(german ? "Offline-Handbuch. Die Hilfe kann beim Arbeiten geöffnet bleiben. Neue Kontoberechtigungen und macOS-Freigaben bestätigst du selbst." : "Offline handbook. Keep help open while working. You confirm new account permissions and macOS access yourself.")</p>
        <nav aria-label="\(german ? "Kapitel" : "Chapters")">\(navigation)</nav>
        <svg viewBox="0 0 640 180" role="img" aria-label="\(german ? "Zwei Dateibereiche mit Ordnerbaum und Dateiliste" : "Two file panes, each with a folder tree and file list")">
        <rect x="2" y="12" width="300" height="150" rx="12"/><rect x="338" y="12" width="300" height="150" rx="12"/>
        <path d="M95 52v100M431 52v100M310 85h20m-8-8 8 8-8 8" stroke="GrayText" fill="none"/>
        <text x="14" y="38">\(left)</text><text x="350" y="38">\(right)</text>
        <text x="14" y="84">▾ /</text><text x="22" y="115">▸ …</text><text x="110" y="84">▣ …</text><text x="110" y="115">□ …</text>
        <text x="350" y="84">▾ /</text><text x="358" y="115">▸ …</text><text x="446" y="84">▣ …</text><text x="446" y="115">□ …</text></svg>
        \(contents)</body></html>
        """
    }
}
